import json
from pathlib import Path
from assembly_record_writer import write_record
p=Path(__file__).with_name('assembly_torres.json')
d=json.loads(p.read_text())
d['kernel']=d['kernel'].replace('Earlier actual OT1999 Records must be screened when this draft is released.', 'Effective earlier Records are Flippo, Lesage, Fiore and Drye. Their search, admissions, certification and tax-lien holdings change no Covenant, jurisdiction or territorial-equality premise. Paul and United Reporting have no effective event or authorship count; their unresolved matters supply no authority here.')
d['blocks']['Opinion Topology']="| Writing | Author | Joined by | Relationship to judgment | Scope joined |\n|---|---|---|---|---|\n| Opinion of the Court | {AUTHOR} | {FULL_JOINERS}; Stone-Zsela as to jurisdiction only | Eight-Justice merits affirmance; unanimous jurisdiction | Seven Associates join the whole opinion; Stone-Zsela joins jurisdiction only |\n| Dissent in part | Stone-Zsela | No other Justice | Would reverse the challenged allocation and remand | Merits and remedy; jurisdiction joined |"
p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
write_record(p,'Kennedy',d['lead_support'],"Stevens assigns Kennedy to articulate the specific constitutional accommodation while retaining residents' constitutional protection and judicial review. Kennedy's Verdugo concurrence addresses that context-sensitive distinction directly and supplies a concrete way to explain why neither consent alone nor an impossibility requirement decides this Covenant. Stevens's own final position adopts the confined accommodation; preserving that scope, rather than creating a general territorial exemption, governs the selection. The ground is settled among all eight, so no expansion accommodation is invented. The displayed balance pool is informational for this Associate assignment; Stone is ineligible for the merits rationale and cannot self-assign it.",True,assigner='Stevens')
